[{"order":1,"type":"heading","text":"Root Detection & Tamper Prevention in Android (Java)"},{"order":2,"type":"paragraph","text":"Protecting Android applications against reverse engineering, debugging, and rooted devices is critical for enterprise, financial, and secure messaging apps. This tutorial covers programmatic checks to detect root access and basic tamper prevention mechanisms using Java."},{"order":3,"type":"subheading","text":"1. Common Indicators of Rooted Devices"},{"order":4,"type":"bullet_point","text":"Presence of well-known binary files like 'su' or 'busybox' in common system directories."},{"order":5,"type":"bullet_point","text":"Installed package names associated with root management apps, such as Superuser or Magisk."},{"order":6,"type":"bullet_point","text":"System build properties indicating a custom or test-keys build (e.g., 'ro.build.tags=test-keys')."},{"order":7,"type":"subheading","text":"2. Implementing Root Detection Checks in Java"},{"order":8,"type":"paragraph","text":"Below is a comprehensive utility class that combines multiple checks, including binary existence, test-keys validation, and checking for dangerous packages."},{"order":9,"type":"code","text":"public class RootUtils {

    public static boolean isDeviceRooted(android.content.Context context) {
        return checkTestKeys() || checkSuBinary() || checkSuperuserPackages(context);
    }

    private static boolean checkTestKeys() {
        String buildTags = android.os.Build.TAGS;
        return buildTags != null && buildTags.contains("test-keys");
    }

    private static boolean checkSuBinary() {
        String[] paths = {
            "/system/app/Superuser.apk",
            "/sbin/su",
            "/system/bin/su",
            "/system/xbin/su",
            "/data/local/xbin/su",
            "/data/local/bin/su",
            "/system/sd/xbin/su",
            "/system/bin/failsafe/su",
            "/data/local/su"
        };
        for (String path : paths) {
            if (new java.io.File(path).exists()) {
                return true;
            }
        }
        return false;
    }

    private static boolean checkSuperuserPackages(android.content.Context context) {
        String[] packages = {
            "com.noshufou.android.su",
            "com.thirdparty.superuser",
            "eu.chainfire.supersu",
            "com.topjohnwu.magisk"
        };
        android.content.pm.PackageManager pm = context.getPackageManager();
        for (String packageName : packages) {
            try {
                pm.getPackageInfo(packageName, 0);
                return true;
            } catch (android.content.pm.PackageManager.NameNotFoundException e) {
                // Package not found, continue checking
            }
        }
        return false;
    }
}"},{"order":10,"type":"subheading","text":"3. Tamper Prevention & Debugging Detection"},{"order":11,"type":"paragraph","text":"In addition to root detection, applications must verify they are not being actively debugged or executed in an unauthorized environment. You can check the application's debug flag programmatically."},{"order":12,"type":"code","text":"public class TamperUtils {

    public static boolean isDebuggerAttached() {
        return android.os.Debug.isDebuggerConnected() || android.os.Debug.waitingForDebugger();
    }

    public static boolean verifyAppSignature(android.content.Context context, String expectedSignatureHash) {
        try {
            android.content.pm.PackageInfo packageInfo = context.getPackageManager().getPackageInfo(
                context.getPackageName(),
                android.content.pm.PackageManager.GET_SIGNATURES
            );
            for (android.content.pm.Signature signature : packageInfo.signatures) {
                java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA256");
                md.update(signature.toByteArray());
                byte[] digest = md.digest();
                StringBuilder sb = new StringBuilder();
                for (byte b : digest) {
                    sb.append(String.format("%02x", b));
                }
                if (sb.toString().equalsIgnoreCase(expectedSignatureHash)) {
                    return true;
                }
            }
        } catch (Exception e) {
            // Handle exception or log securely
        }
        return false;
    }
}"},{"order":13,"type":"subheading","text":"4. Best Practices for Deployment"},{"order":14,"type":"bullet_point","text":"Never rely solely on client-side checks; complement them with server-side attestation APIs like Play Integrity."},{"order":15,"type":"bullet_point","text":"Obfuscate your codebase using tools like ProGuard or DexGuard to make reversing root detection logic harder."},{"order":16,"type":"bullet_point","text":"Execute security checks across multiple threads and handle failures gracefully (e.g., terminating critical flows or wiping local sensitive caches)."}]
